<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility\TemplateSnippetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateSnippetVisibilityService $visibility,
        private readonly TemplateSnippetWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?TemplateSnippetRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Template snippet");
        $span = $this->startSpan("Check allow update usecase for Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?TemplateSnippetRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Template snippet");
        $span = $this->startSpan("Check fixed fields for update usecase for Template snippet");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, TemplateSnippetUpdateParams $params): TemplateSnippetUpdateResult
    {
        $this->logDebug("Run update usecase for Template snippet");
        $span = $this->startSpan("Run update usecase for Template snippet");
        try {
            $ref = new TemplateSnippetRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Template snippet');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new TemplateSnippetUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new TemplateSnippetUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateSnippetUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
